import '../../../core/network/api_client.dart';class AdminSummary{AdminSummary.fromJson(Map<String,dynamic>j):patients=j['totalPatients'] as int,doctors=j['totalDoctors'] as int,pending=j['pendingDoctorApprovals'] as int,alerts=j['unreadAlerts'] as int;final int patients,doctors,pending,alerts;}class DoctorApproval{DoctorApproval.fromJson(Map<String,dynamic>j):id=j['approvalRequestId'] as String,name=j['fullName'] as String,email=j['email'] as String,license=j['licenseNumber'] as String,specialization=j['specialization'] as String?;final String id,name,email,license;final String? specialization;}class AdminRepository{AdminRepository(this._client);final ApiClient _client;Future<AdminSummary>summary()async{final r=await _client.dio.get<Map<String,dynamic>>('/api/admin/dashboard/summary');return AdminSummary.fromJson(r.data!);}Future<List<DoctorApproval>>approvals()async{final r=await _client.dio.get<List<dynamic>>('/api/admin/doctor-approvals/pending');return r.data!.map((e)=>DoctorApproval.fromJson(e)).toList();}Future<void>approve(String id)=>_client.dio.post<void>('/api/admin/doctor-approvals/'+id+'/approve',data:{});Future<void>reject(String id,String reason)=>_client.dio.post<void>('/api/admin/doctor-approvals/'+id+'/reject',data:{'rejectionReason':reason});}